    bio:{dob:"1970",que:"Đang xác minh...",dv:"Đang xác minh...",td:"PGS.TS Tâm lý giáo dục",cv:"2012: Trưởng Khoa Tâm lý–Giáo dục; 2021–5/2024: Phó Hiệu trưởng; 5/2024–nay: Hiệu trưởng; 5/2026–nay: Bí thư Đảng ủy Trường Đại học Sư phạm Hà Nội."},
    contributions:{union:["Quan tâm phát triển đội ngũ, nghiên cứu khoa học và năng lực số cho người học."],school:["Góp phần ổn định, phát triển hơn 150 chương trình đào tạo; thúc đẩy kiểm định chất lượng, mở ngành mới và tích hợp năng lực số vào chương trình giảng dạy."],society:["Phối hợp biên soạn, thẩm định và triển khai chương trình tập huấn giáo viên cốt cán; định hướng chuyển giao tri thức và hỗ trợ chuyên môn cho vùng sâu, vùng xa."]},
    memories:[{type:"quote",title:"Định hướng nhiệm kỳ",text:"Tiếp tục thực hành các giá trị chuẩn mực, sáng tạo, tiên phong; đào tạo những nhà giáo xuất sắc, nhà khoa học và chuyên gia có tinh thần nhân văn, tư duy hiện đại.",source:"Phát biểu nhận nhiệm vụ – Báo Nhân Dân trong cột G"}],sources:{docx:"Hồ sơ Hiệu trưởng - unzip/13. PGS.TS. Nguyễn Đức Sơn /Nội dung  (11).docx",portrait:"Hồ sơ Hiệu trưởng - unzip/13. PGS.TS. Nguyễn Đức Sơn /PGS.TS Nguyễn Đức Sơn.png",references:["Tư liệu chủ đề 5.xlsx – HT-13","https://staff.hnue.edu.vn/directories/?sonnd","https://vietnamnet.vn/pgs-ts-nguyen-duc-son-lam-hieu-truong-truong-dh-su-pham-ha-noi-2278710.html","https://nhandan.vn/pho-giao-su-tien-si-nguyen-duc-son-giu-chuc-hieu-truong-truong-dai-hoc-su-pham-ha-noi-nhiem-ky-2025-2030-post912022.html"]}
