    id:"du01",code:"DU-01",rk:"du",role:"Bí thư Đảng ủy",emoji:"★",name:"GS.NGND. Trần Văn Giàu",period:"1954 – 1956",pc:"truoc1975",image:"./Hồ sơ Bí thư Đảng ủy - đã cập nhât/1. GS. Trần Văn Giàu/1-gs-tran-van-giau26-10-32-40.jpg",
