    contributions:{union:["Bí thư Đảng ủy đầu tiên của Trường Đại học Sư phạm Văn khoa, góp phần đặt nền móng tổ chức Đảng trong các trường đại học đầu tiên của nước Việt Nam mới."],school:["Trực tiếp giảng dạy Chính trị, Triết học và Lịch sử; đào tạo nhiều thế hệ trí thức cách mạng."],society:["Lãnh đạo phong trào cách mạng Nam Bộ; để lại hơn 150 công trình nghiên cứu và sáng lập Giải thưởng khoa học Trần Văn Giàu."]},memories:[{type:"quote",title:"Thầy của những người thầy",text:"Tôi được mọi người khen dạy giỏi là nhờ tôi học ở học trò của mình.",source:"Hồ sơ GS. Trần Văn Giàu"}],sources:{docx:"Hồ sơ Bí thư Đảng ủy - đã cập nhât/1. GS. Trần Văn Giàu/Nội dung.docx",portrait:"Hồ sơ Bí thư Đảng ủy - đã cập nhât/1. GS. Trần Văn Giàu/1-gs-tran-van-giau26-10-32-40.jpg",references:["Chủ đề 5 Cập nhật 06_10_2026.xlsx – DU-01","https://drive.google.com/drive/folders/1KLqWpTW7P51jZxKgeogMHUZwnn82dvF1","https://www.hcmcpv.org.vn/tin-tuc/dong-chi-tran-van-giau-nha-cach-mang-ban-linh-nha-giao-uyen-bac-1491883988","https://nhandan.vn/tieu-su-dong-chi-tran-van-giau-post515408.html","https://tracuusapnhap.vn/xa-cu/an-luc-long/chau-thanh/long-an/"],verificationNotes:["Các nguồn cột G có hai cách ghi ngày sinh: 06/09/1911 (quy đổi từ ngày âm lịch) và 11/09/1911 (hồ sơ lưu trữ); giao diện giữ ngày 11/09/1911 theo hồ sơ lưu trữ và DOCX cập nhật."]}
