  "DT-24": {bio:{td:"Tiến sĩ",cv:"2012–2015: Bí thư Đoàn trường; nhiệm kỳ 2025–2030: Giám đốc Nhà xuất bản Đại học Sư phạm."},contributions:{union:["Bí thư Đoàn trường giai đoạn 2012–2015."],school:["Đảm nhiệm Giám đốc Nhà xuất bản Đại học Sư phạm nhiệm kỳ 2025–2030."],society:["Đang xác minh..."]}},
